import { test, expect } from '@playwright/test';

test.describe('Search Input Focus on Slash Key', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should focus search input when "/" key is pressed', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Verify search input exists but is not focused initially
    await expect(searchInput).toBeVisible();

    // Press the "/" key
    await page.keyboard.press('/');

    // Verify the search input is now focused
    await expect(searchInput).toBeFocused();
  });

  test('should allow typing in search input after "/" key focuses it', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Press "/" to focus the search input
    await page.keyboard.press('/');

    // Verify input is focused
    await expect(searchInput).toBeFocused();

    // Type in the search input
    await page.keyboard.type('test query');

    // Verify the text was entered
    await expect(searchInput).toHaveValue('test query');
  });

  test('should not interfere with "/" character in other contexts', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Click on the search input to focus it manually
    await searchInput.click();

    // Type "/" character directly
    await page.keyboard.type('/');

    // Verify "/" was typed in the input
    await expect(searchInput).toHaveValue('/');
  });

  test('should maintain focus on search input after "/" key press', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Press "/" to focus
    await page.keyboard.press('/');

    // Verify focus
    await expect(searchInput).toBeFocused();

    // Press "/" again while focused
    await page.keyboard.press('/');

    // Verify it remains focused
    await expect(searchInput).toBeFocused();
  });
});
